style.css:
@-moz-document domain("gizmo.ai") {
body {
    font-family: 'Montserrat', sans-serif;
    background-color: #f0f4f8;
    color: #2c3e50;
    margin: 0;
    padding: 0;
  }

  /* Header styling */
  header {
    background: #3498db;
    color: #fff;
    padding: 1.5rem;
    text-align: center;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
  }

  header h1 {
    margin: 0;
    font-size: 2.5rem;
    font-weight: 300;
    letter-spacing: 1px;
  }

  /* Navigation bar styling */
  nav {
    background: #2980b9;
    color: #fff;
    padding: 1rem;
    display: flex;
    justify-content: center;
    align-items: center;
  }

  nav ul {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
  }

  nav ul li {
    margin: 0 1rem;
  }

  nav ul li a {
    color: #fff;
    text-decoration: none;
    font-size: 1.1rem;
    transition: color 0.3s ease;
  }

  nav ul li a:hover {
    color: #b3e5fc;
  }

  /* Main content styling */
  main {
    padding: 2rem;
    background-color: #fff;
    border-radius: 8px;
    margin: 2rem auto;
    max-width: 800px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  }

  main h2 {
    font-size: 2rem;
    color: #3498db;
    margin-bottom: 1rem;
  }

  main p {
    line-height: 1.6;
  }

  /* Button styling */
  button {
    background: #3498db;
    color: #fff;
    border: none;
    padding: 0.5rem 1rem;
    font-size: 1rem;
    border-radius: 4px;
    cursor: pointer;
    transition: background 0.3s ease;
  }

  button:hover {
    background: #2980b9;
  }

  /* Footer styling */
  footer {
    background: #3498db;
    color: #fff;
    text-align: center;
    padding: 1rem 0;
    position: fixed;
    bottom: 0;
    width: 100%;
    box-shadow: 0 -4px 6px rgba(0, 0, 0, 0.1);
  }

  footer p {
    margin: 0;
  }
}
